<?php
declare(strict_types=1);
require_once __DIR__ . '/auth.php';
$account = require_role($requiredRole);
$pdo = db();
$appointmentSql = "SELECT a.id, a.full_name, a.email, a.phone, a.message, a.status, a.created_at, a.appointment_type, a.preferred_at, a.doctor_email, s.name AS service_name FROM appointment_requests a INNER JOIN services s ON s.id = a.service_id";
if ($requiredRole === 'doctor') {
    $appointmentSql .= " WHERE a.doctor_email = ? OR a.doctor_email IS NULL";
    $appointmentQuery = $pdo->prepare($appointmentSql . ' ORDER BY a.created_at DESC LIMIT 100');
    $appointmentQuery->execute([$account['email']]);
    $appointments = $appointmentQuery->fetchAll();
    $newCountQuery = $pdo->prepare("SELECT COUNT(*) FROM appointment_requests WHERE status = 'new' AND (doctor_email = ? OR doctor_email IS NULL)");
    $newCountQuery->execute([$account['email']]);
    $newCount = (int) $newCountQuery->fetchColumn();
} else {
    $appointments = $pdo->query($appointmentSql . ' ORDER BY a.created_at DESC LIMIT 100')->fetchAll();
    $newCount = (int) $pdo->query("SELECT COUNT(*) FROM appointment_requests WHERE status = 'new'")->fetchColumn();
}
$appointmentNotice = (string) ($_GET['appointment'] ?? '');
$appointmentNotices = [
    'scheduled' => 'The appointment has been scheduled and the patient request updated.',
    'invalid' => 'Choose a valid future appointment time.',
    'unavailable' => 'This appointment could not be scheduled. It may have been cancelled or assigned to another doctor.',
];
$title = $requiredRole === 'doctor' ? 'Clinical workspace' : 'Care coordination';
$heading = $requiredRole === 'doctor' ? 'Patient requests.' : 'Appointment requests.';
$description = $requiredRole === 'doctor' ? 'Review incoming requests and prepare for the patient’s next step in care.' : 'Track new appointment requests and coordinate each patient’s next step.';
?>
